# qx2_rotate :: ([1, 2, 3, 4], 1)
def qx2_rotate(xs, k):
    if not xs:
        return xs
    k = k % len(xs)
    return xs[k:] + xs[:k]

if __name__ == '__main__':
    print(qx2_rotate(([1, 2, 3, 4], 1)))

